node --experimental-transform-types --disable-warning=ExperimentalWarning --input-type=module <<'JS'
import { registerHooks } from 'node:module';
registerHooks({ resolve(s, c, next) {
  if (s.startsWith('.') && s.endsWith('.js') && //(src|tools)//.test(c.parentURL ?? ''))
    return next(s.replace('/dist/', '/src/').replace(/\.js$/, '.ts'), c);
  return next(s, c);
}});
const { installVendor } = await import('./tools/node-vendor.mjs');
await installVendor({ reference: true });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { imageFromCode, runImage } = await import('./src/typed/backend/index.ts');
const source = `function mix(a: i32): i32 { return (a ^ 31) & 15; }
function probe(work: buffer, out: buffer, slots: buffer): i32 {
    let i = 0;
    while (i < work.length && i < out.length) {
        const k = mix(work.charCodeAt(i));
        slots.setCharCodeAt(k, ((i << 5) | k) + 32768);
        out.setCharCodeAt(i, slots.charCodeAt(k));
        i = i + 1;
    }
    return (out.charCodeAt(1) >>> 5) & 7;
}`;
const slots = Array(16).fill(0);
const inputs = { mix: { a: [0, 255] }, probe: {
  work: { buffer: [2, 2], cell: [0, 255] }, out: { cells: [0, 0] },
  slots: { buffer: [16, 16], cell: [0, 0] }
}};
const project = projectSource('feature-probe', {'project.json': JSON.stringify({inputs, pipeline:'speed'}), 'main.typed': source});
const p = Program.fromProject(project);
const base = p.exec('probe', [[0, 255], [0, 0], slots], { limit: 20000 });
const ref = globalThis.typedRv32.compile(source, [], undefined);
const image = imageFromCode('probe', ref.image, ref.entries);
const oracle = p.check({ count: 4, against: (name, c) => runImage(image, name, c.args, c.memory, { limit: 200000 }) });
const pipeline = await p.pipeline('speed', { count: 4 });
const checked = p.check({ count: 4 });
const generated = p.cases('probe', { count: 1 })[0];
const frame = 'function frame(p: i32): i32 { const a = new Int32Array(16); a[p] = 7; return a[p]; }';
const normal = new Program('frame_default',frame);
const tape = new Program('frame_tape',frame,{ingest:{ tape:true }});
console.log(JSON.stringify({ result: base.result, trap: base.trap, cells: base.buffers[1].cells, steps: base.steps, generatedItems: generated.items, oracle: oracle.status, checked: checked.status, passes: pipeline.steps.filter(s => s.edits).map(s => s.pass), defaultArray:normal.error, tapeArray:tape.status, tapeResult:tape.exec('frame',[2]).result }));
if (base.result !== 1 || base.trap || base.buffers[1].cells.join() !== '32783,32800' || oracle.status !== 'agree' || checked.status !== 'agree') process.exitCode = 1;
