node --experimental-transform-types --disable-warning=ExperimentalWarning --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { registerHooks } from 'node:module';
registerHooks({ resolve(s, c, next) {
  if (s.startsWith('.') && s.endsWith('.js') && //(src|tools)//.test(c.parentURL ?? ''))
    return next(s.replace('/dist/', '/src/').replace(/\.js$/, '.ts'), c);
  return next(s, c);
}});
const { installVendor } = await import('./tools/node-vendor.mjs');
await installVendor({ reference: true });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { storeOf } = await import('./src/typed/ir.ts');
const { casesFrom, evaluate, agrees, readBuffer } = await import('./src/typed/evaluate.ts');
const { lowerToImage, imageFromCode, runImage } = await import('./src/typed/backend/index.ts');
const design = readFileSync('ttmp/2026/11/26/IRWB-014--lz-style-compressor-and-decompressor-corpus-project/design-doc/01-lz-style-compressor-and-decompressor-corpus-design.md','utf8');
const manifest = design.match(/```json
([\s\S]*?)
```/)[1];
const source = `function roundTrip(work: buffer, policy: buffer, packed: buffer, heads: buffer, prev: buffer, decoded: buffer): i32 {
  decoded.setCharCodeAt(0, work.length + policy.charCodeAt(0) + packed.length + heads.length + prev.length);
  return decoded.charCodeAt(0);
}`;
const p = Program.fromProject(projectSource('abi-probe', {'project.json': manifest, 'main.typed': source}));
const st = storeOf(p.origin.value);
const cases = casesFrom(st, 'roundTrip', { inputs:p.inputs.roundTrip, count:40, seed:7 });
const own = lowerToImage(p.origin, { chains:true, coalesce:true, homes:true }).image;
const ref = globalThis.typedRv32.compile(source, [], undefined);
const reference = imageFromCode('abi-probe', ref.image, ref.entries);
const caps = new Set(), lengths = new Set();
for (const c of cases) {
  const [work, policy, packed, heads, prev, decoded] = c.items.map(item => readBuffer(c.memory, item.at));
  assert.deepEqual([policy.length, packed.length, heads.length, prev.length, decoded.length], [1,24,16,24,24]);
  caps.add(policy[0]);
  lengths.add(work.length);
  const baseline = evaluate(st, c.fn, c.args, c.memory, { limit:20000 });
  assert.equal(baseline.result, work.length + policy[0] + 64);
  for (const image of [own, reference]) {
    const run = runImage(image, c.fn, c.args, c.memory, { limit:200000 });
    assert.equal(run.limit, false);
    assert(agrees(baseline, run));
  }
}
assert.equal(caps.size,4);
console.log(JSON.stringify({validManifest:true, cases:cases.length, caps:[...caps].sort(), distinctLengths:lengths.size, evaluatorAndBothRv32Images:'agree'}));
